    # ---- 非法结构 INPUT/2 ----

    def test_capacities_container_and_items_are_input(self):
        item_cases = [
            [{"id": "a", "cap": "1"}],  # cap 类型
            [{"id": "a", "cap": 1.0}],
            [{"id": "a", "cap": 0}],    # 下界
            [{"id": "a", "cap": 10 ** 6 + 1}],  # 上界
            [{"id": "a", "cap": True}],          # bool
            [{"id": "a", "cap": None}],
            [{"id": 1, "cap": 1}],      # id 类型
            [{"id": "", "cap": 1}],     # id 空串
            [{"cap": 1, "id": "a"}],    # 项键序反
            [{"id": "a"}],              # 缺 cap
            [{"cap": 1}],               # 缺 id
            [{"id": "a", "cap": 1, "x": 0}],  # 多项
            [{"id": "a", "cap": 1}, {"id": "a", "cap": 2}],  # 重复 id
        ]
        for bad in item_cases:
            self.assert_failure(
                encode_ops([
                    {"op": "ci", "config": config_v10(1, capacities=bad),
                     "now": 0},
                ]),
                2, "INPUT",
            )
        # 非数组容器：dict/None/字符串/整数，整体替换 capacities 字段。
        for bad in ({}, None, "x", 1):
            cfg = config_v10(1)
            cfg["capacities"] = bad
            self.assert_failure(
                encode_ops([{"op": "ci", "config": cfg, "now": 0}]),
                2, "INPUT",
            )

