            {"op": "ep", "id": "b1", **self.EP1},
            self.es(items, 50, 100, 10),
            self.open_cid("c1", 15),
            self.ed(100),
            # c0 无快照按 null 比较而保留：get 仍可查到。
            {"op": "get", "cid": "c0"},
            # target=null 已清除端点登记：er 不再列出 b1。
            {"op": "er", "now": 100},
